{
  "name": "Cobolt激光器",
  "name_en": "Cobolt laser source",
  "manufacturer": "Cobolt",
  "description": "Cobolt激光器是一种实验室激光光源，常用于光学搭建、样品激发、光路对准及其他需要稳定激光输出的实验。该类设备通常可通过串口通信进行控制与状态交互。",
  "description_en": "A Cobolt laser source is a laboratory laser used for optical setups, sample excitation, beam alignment, and other experiments that require stable laser output. This type of device is commonly controlled and queried through a serial communication interface.",
  "tag_hints": [
    "laser source",
    "serial communication",
    "optical alignment",
    "sample excitation",
    "lab optics"
  ],
  "actions": [
    {
      "action_name": "auto-is_open",
      "description": "检查与激光器的串口连接是否已打开",
      "description_en": "Check whether the serial connection to the laser is open."
    },
    {
      "action_name": "auto-open",
      "description": "打开与激光器的串口连接",
      "description_en": "Open the serial connection to the laser."
    },
    {
      "action_name": "auto-close",
      "description": "关闭与激光器的串口连接",
      "description_en": "Close the serial connection to the laser."
    },
    {
      "action_name": "auto-flush",
      "description": "清空与激光器串口通信的缓冲区",
      "description_en": "Flush the serial communication buffers for the laser."
    },
    {
      "action_name": "auto-read",
      "description": "从激光器串口读取数据",
      "description_en": "Read data from the laser over the serial interface."
    },
    {
      "action_name": "auto-write",
      "description": "向激光器串口写入数据或命令",
      "description_en": "Write data or commands to the laser over the serial interface."
    }
  ]
}

